package com.vynedam.stockai.controller; import com.vynedam.stockai.dto.OperationsDtos.ProductRequest; import com.vynedam.stockai.model.Product; import com.vynedam.stockai.service.ProductService; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/products")public class ProductController{private final ProductService s;public ProductController(ProductService x){s=x;}@GetMapping List<Product>list(){return s.list();}@PostMapping@PreAuthorize("hasAnyRole('SUPER_ADMIN','STORE_MANAGER','PRODUCTION_MANAGER')")ResponseEntity<Product>create(@Valid@RequestBody ProductRequest r){return ResponseEntity.status(201).body(s.create(r));}@PutMapping("/{id}")@PreAuthorize("hasAnyRole('SUPER_ADMIN','STORE_MANAGER','PRODUCTION_MANAGER')")Product update(@PathVariable String id,@Valid@RequestBody ProductRequest r){return s.update(id,r);}}
